const input = $input.item.json.input || $input.item.json.query || '';
const question = input.toLowerCase();

const faqs = {
  'upfront': 'Brightroof Plus requires zero upfront cost. You pay a fixed monthly subscription from £69 and own the system from day one.',
  'contract': 'Brightroof subscriptions run for 20 years with full maintenance, insurance and battery replacement included.',
  'installation': 'Installation typically takes one day. Brightroof handles all paperwork, grid connection, and MCS certification.',
  'battery': 'All Brightroof Plus systems include a battery. Replacement is free under the subscription.',
  'export': 'Yes — Brightroof customers can export surplus energy back to the grid and earn export tariff payments.',
  'mortgage': 'Unlike roof lease schemes, Brightroof customers own their system outright, so there are no mortgage complications.',
  'maintenance': 'All maintenance is included in the subscription. Brightroof monitors your system 24/7 and resolves issues proactively.',
  'cancel': 'Early termination fees apply. Contact Brightroof to discuss your specific situation.',
  'save': 'In more than 8 out of 10 cases the monthly energy saving exceeds the subscription cost from day one.',
  'cost': 'Brightroof Plus subscriptions start from £69 per month with no upfront cost.',
  'price': 'Brightroof Plus subscriptions start from £69 per month with no upfront cost.',
  'monthly': 'Brightroof Plus subscriptions start from £69 per month with no upfront cost.',
  'subscription': 'Brightroof Plus subscriptions start from £69 per month with no upfront cost. You own the system from day one.',
  'plan': 'Brightroof offers Brightroof Plus — a subscription from £69 per month with zero upfront cost, full maintenance, and battery replacement included.'
};

const matchedKey = Object.keys(faqs).find(key => question.includes(key));
return matchedKey ? 
  faqs[matchedKey] : 
  'Please contact Brightroof directly for more information on this topic.';

const input = $input.item.json.input || '';
const monthlyBill = parseFloat(input.match(/£?(\d+)/)?.[1]) || 150;
const propertyType = input.toLowerCase().includes('detached') ? 'detached' :
                     input.toLowerCase().includes('semi') ? 'semi-detached' : 'house';

const baseSubscription = propertyType === 'detached' ? 89 : 
                         propertyType === 'semi-detached' ? 79 : 69;

const estimatedSaving = monthlyBill * 0.7;
const netMonthlyBenefit = estimatedSaving - baseSubscription;

return `Based on your ${propertyType} with a £${monthlyBill} monthly bill:
- Estimated Brightroof Plus subscription: £${baseSubscription} per month
- Estimated monthly energy saving: £${estimatedSaving.toFixed(0)}
- Net monthly benefit: ${netMonthlyBenefit > 0 ? `£${netMonthlyBenefit.toFixed(0)} better off per month` : 'savings depend on usage patterns'}
- No upfront cost required`;

try {
  const agentResponse = ($input.item.json.output || '').trim();
  const webhookData = $('Webhook trigger').item.json.body;

  // Find the tag at the end, allowing small variations like "COMPLEX: COMPLEX"
  const tagMatch = agentResponse.match(/(COMPLEXITY|COMPLEX)\s*:\s*(SIMPLE|COMPLEX)\s*$/i);
  const tag = tagMatch ? tagMatch[2].toUpperCase() : null;

  // Fail safe: anything not clearly SIMPLE goes to a human
  const complexity = tag === 'SIMPLE' ? 'simple' : 'complex';

  // Remove the tag from the reply
  const cleanResponse = tagMatch
    ? agentResponse.slice(0, tagMatch.index).trim()
    : agentResponse;

  return [{
    json: {
      customer_name: webhookData.customer_name,
      customer_email: webhookData.customer_email,
      query: webhookData.query,
      agent_response: cleanResponse,
      complexity: complexity
    }
  }];
} catch (e) {
  return [{ json: { error: e.message, complexity: 'complex' } }];
}
